function fillEventFilters(){const s={season:new Set(),league:new Set(),track:new Set(),comp:new Set()};for(const [y,ei] of eventIndex){const d=eventData(y,ei),r=d.r;s.season.add(y);s.league.add(val(r[8]));s.track.add(val(r[9]));s.comp.add(val(r[10]))}options('eventSeason',s.season,'Wszystkie sezony',(a,b)=>+b-+a);options('eventLeague',s.league,'Wszystkie ligi / kraje');options('eventTrack',s.track,'Wszystkie tory');options('eventComp',s.comp,'Wszystkie rozgrywki')}
function openEvents(){currentEvent=null;$('searchPanel').classList.add('hidden');$('home').classList.add('hidden');$('profile').classList.add('hidden');$('filtersPanel').classList.add('hidden');$('resultsSection').classList.add('hidden');$('compareSection').classList.add('hidden');$('eventDetail').classList.add('hidden');$('eventsSection').classList.remove('hidden');fillEventFilters();applyEventFilters();scrollTo({top:0,behavior:'smooth'})}
function eventTitle(d){const r=d.r,h=val(r[5]),g=val(r[6]);return d.team?`${h} – ${g}`:(val(r[10])||val(r[8])||val(r[9])||'Zawody')}
function eventCardHTML(d){const r=d.r,score=val(r[7]),league=val(r[8]),track=val(r[9]),comp=val(r[10]),round=val(r[11]),meta=[league,track,d.team?comp:'',round].filter(Boolean).join(' • ');return `<article class="eventCard" data-event-y="${d.y}" data-event-i="${d.ei}"><div class="eventCardTop"><div style="min-width:0"><div class="eventYear">${esc(d.y)}</div><h3>${esc(eventTitle(d))}</h3><div class="eventMeta">${esc(meta)}</div></div>${score?`<div class="scorePill">${esc(score)}</div>`:''}</div><div class="eventFoot"><span class="eventKind">${d.team?'mecz drużynowy':'zawody indywidualne'} • ${d.count} uczestników</span><span class="eventOpen">Otwórz →</span></div></article>`}
function applyEventFilters(){eventShown=60;const q=norm($('eventQ').value),fy=$('eventSeason').value,ft=$('eventType').value,fl=$('eventLeague').value,ftr=$('eventTrack').value,fc=$('eventComp').value;eventFiltered=eventIndex.filter(([y,ei,text,type])=>{if(fy&&y!==fy)return false;if(ft&&type!==ft)return false;const d=eventData(y,ei),r=d.r;if(fl&&val(r[8])!==fl)return false;if(ftr&&val(r[9])!==ftr)return false;if(fc&&val(r[10])!==fc)return false;if(q&&!text.includes(q))return false;return true});renderEventList()}
function renderEventList(){const box=$('eventList');$('eventCount').textContent=`${eventFiltered.length.toLocaleString('pl-PL')} wydarzeń`;$('eventShown').textContent=eventFiltered.length?`Pokazano ${Math.min(eventShown,eventFiltered.length)} z ${eventFiltered.length}`:'';if(!eventFiltered.length){box.innerHTML='<div class="panel eventEmpty">Brak meczów lub zawodów dla wybranych kryteriów.</div>';$('eventMore').classList.add('hidden');return}const part=eventFiltered.slice(0,eventShown);let html='',last='';for(const [y,ei] of part){if(y!==last){html+=`<div class="yearHead"><b>${esc(y)}</b></div>`;last=y}html+=eventCardHTML(eventData(y,ei))}box.innerHTML=html;box.querySelectorAll('[data-event-y]').forEach(x=>x.onclick=()=>openEventDetail(x.dataset.eventY,+x.dataset.eventI,'events'));$('eventMore').classList.toggle('hidden',eventShown>=eventFiltered.length)}
function clearEventFilters(){$('eventQ').value='';['eventSeason','eventLeague','eventTrack','eventComp','eventType'].forEach(id=>$(id).value='');applyEventFilters()}
function participantHTML(r){const pid=r[0],p=DB.players[pid],pts=val(r[1])||'—',heats=val(r[2]),place=[val(r[3]),val(r[4])].filter(Boolean).join(' '),notes=val(r[13]);const sub=[heats?`Biegi: ${heats}`:'',place,notes].filter(Boolean).join(' • ');return `<div class="participant"><div class="participantMain"><div class="participantName" data-participant-pid="${pid}">${esc(p?.[0]||'—')}</div>${sub?`<div class="participantSub">${esc(sub)}</div>`:''}</div><div class="participantPts">${esc(pts)}<small>pkt</small></div></div>`}
function openEventDetail(y,ei,from='events'){const d=eventData(String(y),+ei);if(!d)return;currentEvent=[String(y),+ei];eventReturnView=from;hideMainViews();$('compareSection').classList.add('hidden');$('playerAnalytics').classList.add('hidden');$('eventsSection').classList.add('hidden');$('searchPanel').classList.add('hidden');$('eventDetail').classList.remove('hidden');const r=d.r,score=val(r[7]),league=val(r[8]),track=val(r[9]),comp=val(r[10]),round=val(r[11]),cap=val(r[12]);$('eventDetailYear').textContent=d.y;$('eventDetailTitle').textContent=eventTitle(d);$('eventDetailScore').textContent=score||'';$('eventDetailScore').classList.toggle('hidden',!score);$('eventDetailMeta').textContent=[league,track,comp,round,cap?`Pojemność: ${cap}`:'',`${d.count} uczestników`].filter(Boolean).join(' • ');const rows=DB.years[d.y].slice(d.start,d.start+d.count);$('participants').innerHTML=rows.map(participantHTML).join('');$('participants').querySelectorAll('[data-participant-pid]').forEach(x=>x.onclick=()=>selectPlayer(+x.dataset.participantPid));scrollTo({top:0,behavior:'smooth'})}
function closeEventDetail(){if(eventReturnView==='profile'&&currentPid!==null){$('eventDetail').classList.add('hidden');selectPlayer(currentPid)}else{$('eventDetail').classList.add('hidden');$('eventsSection').classList.remove('hidden');$('searchPanel').classList.add('hidden');scrollTo({top:0,behavior:'smooth'})}}
function eventFromRow(y,i){const ei=rowEventMap[y]?.[i];return Number.isInteger(ei)&&ei>=0?ei:null}
function cardV4(y,r,i){const pts=val(r[1])||'—',heats=val(r[2]),e=val(r[3]),f=val(r[4]),g=val(r[5]),h=val(r[6]),score=val(r[7]),league=val(r[8]),track=val(r[9]),comp=val(r[10]),round=val(r[11]),cap=val(r[12]),notes=val(r[13]);const team=!!(g&&h&&score),title=comp||league||'Wynik',sec=[league,track,round].filter(Boolean).join(' • ');let mid='';if(team)mid=`<div class="match"><span><b>${esc(g)}</b> – ${esc(h)}</span><span><b>${esc(score)}</b></span></div>`;else{const ex=[e,f,g,h].filter(Boolean);if(ex.length)mid=`<div class="extras">${esc(ex.join(' • '))}</div>`}const extra=[cap?`Pojemność: ${cap}`:'',notes?`Uwagi: ${notes}`:''].filter(Boolean).join(' • '),ei=eventFromRow(y,i);return `<article class="card"><div class="cardTop"><div><div class="eventTitle">${esc(title)}</div><div class="secondary">${esc(sec)}</div></div><div class="pts">${esc(pts)}<small>pkt</small></div></div>${mid}${heats?`<div class="heat">Biegi: ${esc(heats)}</div>`:''}${extra?`<div class="extras">${esc(extra)}</div>`:''}${ei!==null?`<button class="eventFromResult" data-profile-event-y="${esc(y)}" data-profile-event-i="${ei}">🏁 Otwórz pełną kartę zawodów</button>`:''}</article>`}
renderResults=function(){const box=$('results');if(!filtered.length){box.innerHTML='<div class="panel empty">Brak wyników dla wybranych filtrów.</div>';$('loadMore').classList.add('hidden');$('shownInfo').textContent='';return}const part=filtered.slice(0,shown);let html='',last='';for(const [y,r,i] of part){if(y!==last){html+=`<div class="yearHead"><b>${esc(y)}</b></div>`;last=y}html+=cardV4(y,r,i)}box.innerHTML=html;box.querySelectorAll('[data-profile-event-y]').forEach(x=>x.onclick=()=>openEventDetail(x.dataset.profileEventY,+x.dataset.profileEventI,'profile'));$('loadMore').classList.toggle('hidden',shown>=filtered.length);$('shownInfo').textContent=`Pokazano ${Math.min(shown,filtered.length)} z ${filtered.length}`};

$('eventsBtn').onclick=openEvents;$('homeEvents').onclick=openEvents;$('eventsBack').onclick=goHome;$('eventDetailBack').onclick=closeEventDetail;$('eventSearchBtn').onclick=applyEventFilters;$('eventQ').addEventListener('input',applyEventFilters);$('eventQ').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();applyEventFilters()}});['eventSeason','eventType','eventLeague','eventTrack','eventComp'].forEach(id=>$(id).addEventListener('change',applyEventFilters));$('eventClear').onclick=clearEventFilters;$('eventMore').onclick=()=>{eventShown+=60;renderEventList()};

// ===== v4.3: analityka, deep-linki i naturalna historia widoków =====
let routeApplying=false,initialRouteApplied=false;

function renderLatestEvents(){
  const box=$('latestEvents');if(!box)return;
  const newestSeason=eventIndex[0]?.[0];
  const refs=CORE.latestEventRefs(eventIndex.filter(([y])=>y===newestSeason).map(([y,ei,,,key])=>({season:y,order:ei,key,y,ei})),10);
  box.innerHTML=refs.length?refs.map(({y,ei})=>eventCardHTML(eventData(y,ei))).join(''):'<div class="empty">Najnowsze wydarzenia pojawią się po wczytaniu bazy.</div>';
  box.querySelectorAll('[data-event-y]').forEach(x=>x.onclick=()=>openEventDetail(x.dataset.eventY,+x.dataset.eventI,'home'));
}

function chartSeries(containerId,valueId,series){
  const box=$(containerId),status=$(valueId);if(!box)return;
  const years=[...new Set(series.flatMap(item=>item.stats.filter(x=>x.avg!==null).map(x=>x.season)))].sort((a,b)=>+a-+b);
  const values=series.flatMap(item=>item.stats.map(x=>x.avg).filter(x=>x!==null));
  if(!years.length||!values.length){box.innerHTML='<div class="chartEmpty">Brak liczbowych wyników do narysowania wykresu.</div>';if(status)status.textContent='';return}
  const width=720,height=260,left=42,right=18,top=20,bottom=42,plotW=width-left-right,plotH=height-top-bottom,maxY=Math.max(1,Math.ceil(Math.max(...values))),yearX=new Map(years.map((year,index)=>[year,left+(years.length===1?plotW/2:index*plotW/(years.length-1))]));
  let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Wykres średniej biegowej w sezonach">`;
  for(let i=0;i<=4;i++){const value=maxY*(4-i)/4,y=top+i*plotH/4;svg+=`<line class="chartGrid" x1="${left}" y1="${y}" x2="${width-right}" y2="${y}"></line><text class="chartAxis" x="${left-7}" y="${y+4}" text-anchor="end">${fmtNum(value,1)}</text>`}
  const labelStep=Math.max(1,Math.ceil(years.length/8));years.forEach((year,index)=>{if(index%labelStep===0||index===years.length-1)svg+=`<text class="chartAxis" x="${yearX.get(year)}" y="${height-15}" text-anchor="middle">${esc(year)}</text>`});
  series.forEach((item,seriesIndex)=>{const points=item.stats.filter(x=>x.avg!==null).sort((a,b)=>+a.season-+b.season).map(stat=>({stat,x:yearX.get(stat.season),y:top+(maxY-stat.avg)*plotH/maxY}));if(points.length>1)svg+=`<path class="chartLine" style="stroke:${item.color}" d="${points.map((point,index)=>`${index?'L':'M'} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(' ')}"></path>`;for(const point of points){const label=`${item.name} • ${point.stat.season}: ${fmtNum(point.stat.avg,3)} pkt/bieg`;svg+=`<g class="chartPoint" tabindex="0" data-chart-label="${esc(label)}"><circle cx="${point.x}" cy="${point.y}" r="${seriesIndex?5:5.5}" style="fill:${item.color}"></circle><title>${esc(label)}</title></g>`}});
  svg+='</svg>';box.innerHTML=svg;
  const show=e=>{if(status)status.textContent=e.currentTarget.dataset.chartLabel};box.querySelectorAll('[data-chart-label]').forEach(point=>{point.addEventListener('pointerenter',show);point.addEventListener('focus',show);point.addEventListener('click',show)});if(status){const latest=series.flatMap(item=>item.stats.filter(x=>x.avg!==null).map(stat=>({item,stat}))).sort((a,b)=>+b.stat.season-+a.stat.season)[0];status.textContent=latest?`${latest.item.name} • ${latest.stat.season}: ${fmtNum(latest.stat.avg,3)} pkt/bieg`:''}
}

function playerScope(){const parts=[$('track').value,$('season').value&&`sezon ${$('season').value}`,$('league').value,$('comp').value,$('within').value&&`„${$('within').value.trim()}”`].filter(Boolean);return parts.length?parts.join(' • '):'cała kariera'}

renderStats=function(){const metric=cmpMetric(filtered),active=playerScope()!=='cała kariera';$('statCount').textContent=metric.starts.toLocaleString('pl-PL');$('statHeats').textContent=metric.heats.toLocaleString('pl-PL');$('statPoints').textContent=fmtPointsMetric(metric);$('statSeasons').textContent=metric.seasons.toLocaleString('pl-PL');$('statAvg').textContent=fmtNum(metric.avg);$('statHeatAvg').textContent=fmtNum(metric.heatAvg,3);$('statBest').textContent=fmtScore(metric.best);$('statScope').textContent=`Statystyki: ${playerScope()}`;$('statsClear').classList.toggle('hidden',!active);$('resultCount').textContent=`${filtered.length.toLocaleString('pl-PL')} wyników`};

function renderPlayerAnalytics(){
  if(currentPid===null)return;$('playerAnalytics').classList.remove('hidden');
  const stats=CORE.seasonStats(metricRecords(filtered));
  $('seasonStats').innerHTML=stats.map(item=>`<article class="seasonStat"><strong>${esc(item.season)}</strong><div><span>Starty <b>${item.starts.toLocaleString('pl-PL')}</b></span><span>Biegi <b>${item.heats.toLocaleString('pl-PL')}</b></span><span>Punkty <b>${fmtScore(item.total)}${item.bonus?`+${fmtScore(item.bonus)}`:''}</b></span><span>Bonusy <b>${fmtScore(item.bonus)}</b></span><span>Śr. pkt / wynik <b>${fmtNum(item.avg)}</b></span><span>Śr. biegowa <b>${fmtNum(item.heatAvg,3)}</b></span><span>Najlepszy wynik <b>${fmtScore(item.best)}</b></span></div></article>`).join('')||'<div class="empty">Brak wyników sezonowych dla wybranych filtrów.</div>';
  $('playerChartTitle').textContent=`Średnia biegowa w sezonach${$('track').value?` • ${$('track').value}`:''}`;
  chartSeries('playerChart','playerChartValue',[{name:DB.players[currentPid][0],stats:stats.map(item=>({...item,avg:item.heatAvg})),color:'#ff8b45'}]);
}

function renderComparisonChart(leftStats,rightStats,leftName,rightName){chartSeries('cmpChart','cmpChartValue',[{name:leftName,stats:leftStats.map(item=>({...item,avg:item.heatAvg})),color:'#ff8b45'},{name:rightName,stats:rightStats.map(item=>({...item,avg:item.heatAvg})),color:'#69a7ff'}]);$('cmpLegend').innerHTML=`<span><i style="background:#ff8b45"></i>${esc(leftName)}</span><span><i style="background:#69a7ff"></i>${esc(rightName)}</span>`}

function comparisonEventRows(rows){
  const unique=new Map();
  for(const [y,row,index] of rows){const ei=eventFromRow(y,index);if(ei===null)continue;const key=eventRefKeys.get(`${y}:${ei}`),d=eventData(y,ei);if(!key||!d||unique.has(key))continue;unique.set(key,{key,y,ei,points:val(row[1]),title:eventTitle(d),track:val(d.r[9]),competition:val(d.r[10]),league:val(d.r[8])})}
  return [...unique.values()];
}

function renderCommonEvents(leftRows,rightRows){
  const result=CORE.commonEvents(comparisonEventRows(leftRows),comparisonEventRows(rightRows)),leftName=DB.players[cmpPidA][0],rightName=DB.players[cmpPidB][0];
  const track=$('cmpTrack').value,scope=track?` na torze ${track}`:'';$('commonSummary').innerHTML=`<b>Wspólne zawody${esc(scope)}: ${result.events.length.toLocaleString('pl-PL')}</b><div><span>Więcej punktów — ${esc(leftName)}: <strong>${result.leftWins}</strong></span><span>${esc(rightName)}: <strong>${result.rightWins}</strong></span><span>Remisy: <strong>${result.ties}</strong></span></div><small>Porównanie dotyczy wyników punktowych w tych samych grupach wydarzeń WZDB i korzysta z aktualnych filtrów.</small>`;
  const events=result.events.sort((a,b)=>+b.left.y-+a.left.y||b.left.ei-a.left.ei);
  $('commonEvents').innerHTML=events.length?events.map(item=>{const diff=item.difference===null?'brak porównywalnej wartości':item.difference===0?'remis punktowy':`+${fmtScore(Math.abs(item.difference))} dla ${item.difference>0?leftName:rightName}`;return `<article class="commonEvent" data-common-event="${esc(item.key)}"><div class="eventYear">${esc(item.left.y)}</div><h3>${esc(item.left.competition||item.left.title)}</h3><div class="eventMeta">${esc([item.left.league,item.left.track].filter(Boolean).join(' • '))}</div><div class="commonScores"><span>${esc(leftName)} <b>${esc(item.left.points||'—')} pkt</b></span><span>${esc(rightName)} <b>${esc(item.right.points||'—')} pkt</b></span></div><small>${esc(diff)}</small></article>`}).join(''):'<div class="panel cmpEmpty">Brak wspólnych wydarzeń dla wybranych filtrów.</div>';
  $('commonEvents').querySelectorAll('[data-common-event]').forEach(card=>card.onclick=()=>{const ref=eventKeyMap.get(card.dataset.commonEvent);if(ref)openEventDetail(ref[0],ref[1],'compare')});
}

function currentRoute(){
  if(!$('eventDetail').classList.contains('hidden')&&currentEvent){const key=eventRefKeys.get(`${currentEvent[0]}:${currentEvent[1]}`);if(key)return {view:'event',eventKey:key}}
  if(!$('compareSection').classList.contains('hidden'))return {view:'compare',playerA:cmpPidA===null?'':DB.players[cmpPidA][3],playerB:cmpPidB===null?'':DB.players[cmpPidB][3]};
  if(!$('eventsSection').classList.contains('hidden'))return {view:'events'};
  if(currentPid!==null&&!$('profile').classList.contains('hidden'))return {view:'player',playerKey:DB.players[currentPid][3]};
  return {view:'home'};
}

function controlValues(ids){const values={};for(const id of ids){const node=$(id);if(node)values[id]=node.value}return values}
function setControlValues(values={}){for(const [id,value] of Object.entries(values)){const node=$(id);if(!node)continue;const isTextControl=node.tagName==='INPUT'||node.tagName==='TEXTAREA',hasOption=node.options&&[...node.options].some(option=>option.value===value);if(isTextControl||hasOption)node.value=value}}
function captureViewContext(){
  const route=currentRoute(),context={route,scrollY:Math.max(0,Math.round(window.scrollY||0))};
  if(route.view==='player')Object.assign(context,{controls:controlValues(['season','league','comp','track','within','sort']),shown});
  if(route.view==='events')Object.assign(context,{controls:controlValues(['eventQ','eventSeason','eventType','eventLeague','eventTrack','eventComp']),eventShown});
  if(route.view==='compare')Object.assign(context,{controls:controlValues(['cmpSeason','cmpLeague','cmpComp','cmpTrack']),hasComparison:cmpPidA!==null&&cmpPidB!==null});
  if(route.view==='event')context.eventReturnView=eventReturnView;
  return context;
}

function persistHistoryContext(){if(routeApplying||!DB)return;const context=captureViewContext();history.replaceState({wz43:true,route:context.route,context},'',CORE.urlForRoute(location.href,context.route))}
function pushCurrentRoute(){if(routeApplying||!DB)return;const route=currentRoute(),context=captureViewContext();history.pushState({wz43:true,route,context},'',CORE.urlForRoute(location.href,route))}

async function restoreScroll(value){await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));scrollTo({top:Number(value)||0,behavior:'auto'})}
async function applyRoute(route,context=null){
  const next=CORE.normalizeRoute(route);routeApplying=true;
  try{
    if(next.view==='player'){const pid=findPidByKey(next.playerKey);if(pid<0){goHome();toast('Nie znaleziono zawodnika z udostępnionego linku')}else{selectPlayer(pid);if(context?.controls){setControlValues(context.controls);sortMode=$('sort').value||'new';applyFilters();shown=Math.max(60,Number(context.shown)||60);renderResults()}}}
    else if(next.view==='events'){openEvents();if(context?.controls){setControlValues(context.controls);applyEventFilters();eventShown=Math.max(60,Number(context.eventShown)||60);renderEventList()}}
    else if(next.view==='compare'){const a=findPidByKey(next.playerA),b=findPidByKey(next.playerB);openCompare(a>=0?a:null);if(a>=0){cmpPidA=a;$('cmpA').value=DB.players[a][0]}if(b>=0){cmpPidB=b;$('cmpB').value=DB.players[b][0]}if(a>=0&&b>=0){cmpFillFilters();$('compareFiltersPanel').classList.remove('hidden');if(context?.controls)setControlValues(context.controls);renderComparison()}}
    else if(next.view==='event'){const ref=eventKeyMap.get(next.eventKey);if(!ref){goHome();toast('Nie znaleziono wydarzenia z udostępnionego linku')}else openEventDetail(ref[0],ref[1],context?.eventReturnView||'events')}
    else goHome();
  }finally{routeApplying=false}
  if(context)await restoreScroll(context.scrollY);
}

async function shareUrl(title,url){
  if(navigator.share){try{await navigator.share({title,url});return}catch(error){if(error?.name==='AbortError')return}}
  try{await navigator.clipboard.writeText(url)}catch{const input=document.createElement('textarea');input.value=url;input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();document.execCommand('copy');input.remove()}toast('Link skopiowany')
}

const _activateDBV43=activateDB;
activateDB=async function(db){await _activateDBV43(db);playerSearchIndex=DB.players.map((player,pid)=>({pid,id:pid,key:player[3],tokens:player[3].split(' ')}));renderHome();if(!initialRouteApplied){initialRouteApplied=true;const route=CORE.routeFromUrl(location.href);await applyRoute(route);const context=captureViewContext();history.replaceState({wz43:true,route:context.route,context},'',CORE.urlForRoute(location.href,context.route))}};

activateUpdatedDB=async function(db){const hadDatabase=!!DB,context=hadDatabase?captureViewContext():null;await activateDB(db);if(context){await applyRoute(context.route,context);persistHistoryContext()}};

const _selectPlayerV43=selectPlayer;
selectPlayer=function(pid){if(!routeApplying)persistHistoryContext();const result=_selectPlayerV43(pid);renderPlayerAnalytics();if(!routeApplying)pushCurrentRoute();return result};
const _goHomeV43=goHome;
goHome=function(){if(!routeApplying)persistHistoryContext();$('playerAnalytics').classList.add('hidden');currentEvent=null;const result=_goHomeV43();if(!routeApplying)pushCurrentRoute();return result};
const _openEventsV43=openEvents;
openEvents=function(){if(!routeApplying)persistHistoryContext();$('playerAnalytics').classList.add('hidden');const result=_openEventsV43();if(!routeApplying)pushCurrentRoute();return result};
const _openCompareV43=openCompare;
openCompare=function(prefillPid=null){if(!routeApplying)persistHistoryContext();$('playerAnalytics').classList.add('hidden');const result=_openCompareV43(prefillPid);if(!routeApplying)pushCurrentRoute();return result};
const _openEventDetailV43=openEventDetail;
openEventDetail=function(y,ei,from='events'){if(!routeApplying)persistHistoryContext();$('playerAnalytics').classList.add('hidden');const result=_openEventDetailV43(y,ei,from);if(!routeApplying)pushCurrentRoute();return result};

window.addEventListener('popstate',event=>{if(!DB)return;const route=event.state?.route||CORE.routeFromUrl(location.href);void applyRoute(route,event.state?.context||null)});
$('brand').onclick=()=>goHome();$('eventsBtn').onclick=()=>openEvents();$('homeEvents').onclick=()=>openEvents();$('latestAll').onclick=()=>openEvents();
$('compareBack').onclick=()=>history.length>1?history.back():goHome();$('eventsBack').onclick=()=>history.length>1?history.back():goHome();$('eventDetailBack').onclick=()=>history.length>1?history.back():goHome();
$('playerShare').onclick=()=>{if(currentPid!==null)void shareUrl(`Wyniki: ${DB.players[currentPid][0]}`,CORE.formatPlayerUrl(location.href,DB.players[currentPid][3]))};
$('eventShare').onclick=()=>{if(currentEvent){const key=eventRefKeys.get(`${currentEvent[0]}:${currentEvent[1]}`),d=eventData(currentEvent[0],currentEvent[1]);if(key&&d)void shareUrl(`Wyniki: ${eventTitle(d)}`,CORE.formatEventUrl(location.href,key))}};
$('statsClear').onclick=clearFilters;
['season','league','comp','track','sort'].forEach(id=>$(id).addEventListener('change',persistHistoryContext));$('within').addEventListener('input',persistHistoryContext);$('loadMore').addEventListener('click',persistHistoryContext);
['eventSeason','eventType','eventLeague','eventTrack','eventComp'].forEach(id=>$(id).addEventListener('change',persistHistoryContext));$('eventQ').addEventListener('input',persistHistoryContext);$('eventMore').addEventListener('click',persistHistoryContext);
['cmpSeason','cmpLeague','cmpComp','cmpTrack'].forEach(id=>$(id).addEventListener('change',persistHistoryContext));$('runCompare').addEventListener('click',()=>setTimeout(persistHistoryContext,0));

// ===== v4.4: profil zawodnika, filtry kaskadowe i analiza progu =====
let playerView='results',rowHomeAwayMap={},teamClassification={events:0,classified:0,rows:0,classifiedRows:0};

const _buildEventIndexV44=buildEventIndex;
buildEventIndex=function(){
  _buildEventIndexV44();rowHomeAwayMap={};teamClassification={events:0,classified:0,rows:0,classifiedRows:0};
  for(const y of Object.keys(DB.years)){const rows=DB.years[y],sides=Array(rows.length).fill('UNKNOWN');rowHomeAwayMap[y]=sides;
    for(const [start,count] of DB.events[y]||[]){const eventRows=rows.slice(start,start+count),first=eventRows[0];if(!first||!val(first[5])||!val(first[6])||!val(first[7]))continue;
      teamClassification.events++;teamClassification.rows+=count;
      const classified=CORE.classifyTeamEvent(eventRows.map(row=>({points:val(row[1]),home:val(row[5]),away:val(row[6]),score:val(row[7])})),{home:val(first[5]),away:val(first[6]),score:val(first[7])});
      if(!classified.classified)continue;teamClassification.classified++;teamClassification.classifiedRows+=count;classified.sides.forEach((side,index)=>{sides[start+index]=side});
    }
  }
};

metricRecords=function(rows){return (rows||[]).map(([season,row,index],fallback)=>{const rowIndex=Number.isInteger(index)?index:fallback,ei=eventFromRow(season,rowIndex);return {season,points:val(row[1]),heats:val(row[2]),league:val(row[8]),track:val(row[9]),competition:val(row[10]),home:val(row[5]),away:val(row[6]),score:val(row[7]),round:val(row[11]),homeAway:rowHomeAwayMap[season]?.[rowIndex]||'UNKNOWN',order:rowIndex,rowIndex,eventKey:ei===null?'':eventRefKeys.get(`${season}:${ei}`)||'',ref:[season,row,rowIndex]}})};

function playerFilterValues(){return {season:$('season').value,league:$('league').value,competition:$('comp').value,track:$('track').value,search:$('within').value}}
function setSelectOptions(id,values,label,current){const node=$(id),safe=[...values];if(current&&!safe.includes(current))safe.unshift(current);node.innerHTML=`<option value="">${esc(label)}</option>`+safe.map(value=>`<option value="${esc(value)}">${esc(value)}${value===current&&!values.includes(value)?' • poza zakresem':''}</option>`).join('');node.value=current||''}
function refreshPlayerFilterOptions(){if(currentPid===null)return;const filters=playerFilterValues(),available=CORE.cascadingFilterOptions(metricRecords(currentAll),filters);setSelectOptions('season',available.season,'Wszystkie sezony',filters.season);setSelectOptions('league',available.league,'Wszystkie ligi / kraje',filters.league);setSelectOptions('comp',available.competition,'Wszystkie rozgrywki',filters.competition);setSelectOptions('track',available.track,'Wszystkie tory',filters.track)}
fillFilters=function(){['season','league','comp','track'].forEach(id=>$(id).value='');$('within').value='';refreshPlayerFilterOptions()};

playerScope=function(){const parts=[$('season').value,$('league').value,$('comp').value,$('track').value,$('within').value&&`„${$('within').value.trim()}”`].filter(Boolean);return parts.length?parts.join(' • '):'Cała kariera'};

function setPlayerView(view,{historyUpdate=true}={}){playerView=['results','stats','threshold'].includes(view)?view:'results';$('resultsSection').classList.toggle('hidden',playerView!=='results');$('playerStatsView').classList.toggle('hidden',playerView!=='stats');$('thresholdView').classList.toggle('hidden',playerView!=='threshold');$('playerTabs').querySelectorAll('[data-player-view]').forEach(button=>{const active=button.dataset.playerView===playerView;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});if(playerView==='threshold')renderThreshold();if(historyUpdate&&!routeApplying)persistHistoryContext()}
function hidePlayerV44(){$('playerNav').classList.add('hidden');$('playerStatsView').classList.add('hidden');$('thresholdView').classList.add('hidden')}

applyFilters=function(){if(currentPid===null)return;shown=60;const model=CORE.filterRecords(metricRecords(currentAll),playerFilterValues());filtered=model.map(record=>record.ref);filtered.sort((a,b)=>sortMode==='old'?((+a[0]-+b[0])||(a[2]-b[2])):((+b[0]-+a[0])||(a[2]-b[2])));refreshPlayerFilterOptions();renderStats();renderPlayerAnalytics();renderResults();$('playerScope').textContent=playerScope();renderThreshold()};

function thresholdRecords(){const place=$('thresholdPlace').value;return CORE.filterRecords(metricRecords(filtered),{homeAway:place})}
function thresholdNumber(value,digits=1){return value===null||value===undefined?'—':Number(value).toLocaleString('pl-PL',{minimumFractionDigits:digits,maximumFractionDigits:digits})}
function thresholdChart(analysis){if(!analysis.sample)return '<div class="chartEmpty">Brak liczbowych wyników do narysowania wykresu.</div>';const items=analysis.results,width=720,height=250,left=38,right=18,top=20,bottom=35,plotW=width-left-right,plotH=height-top-bottom,max=Math.max(analysis.threshold,...items.map(item=>item.value),1),min=Math.min(0,analysis.threshold,...items.map(item=>item.value)),range=Math.max(1,max-min),x=index=>left+(items.length===1?plotW/2:index*plotW/(items.length-1)),y=value=>top+(max-value)*plotH/range,thresholdY=y(analysis.threshold);let svg=`<svg class="thresholdChart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Kolejne wyniki względem progu ${analysis.threshold}">`;for(let i=0;i<=4;i++){const value=max-(range*i/4),gy=top+i*plotH/4;svg+=`<line class="chartGrid" x1="${left}" y1="${gy}" x2="${width-right}" y2="${gy}"></line><text class="chartAxis" x="${left-6}" y="${gy+4}" text-anchor="end">${thresholdNumber(value,1)}</text>`}svg+=`<line class="thresholdLine" x1="${left}" y1="${thresholdY}" x2="${width-right}" y2="${thresholdY}"></line><text class="chartAxis" x="${width-right}" y="${Math.max(12,thresholdY-5)}" text-anchor="end">próg ${thresholdNumber(analysis.threshold,1)}</text>`;if(items.length>1)svg+=`<path class="resultLine" d="${items.map((item,index)=>`${index?'L':'M'} ${x(index)} ${y(item.value)}`).join(' ')}"></path>`;items.forEach((item,index)=>{svg+=`<circle class="${item.outcome.toLowerCase()}Point" cx="${x(index)}" cy="${y(item.value)}" r="5"><title>${item.record.season} • ${thresholdNumber(item.value,1)} pkt • ${item.outcome}</title></circle>`});return svg+'</svg>'}
function renderThreshold(){if(currentPid===null||!$('thresholdOutput'))return;const line=$('thresholdLine').value,lastN=+$('thresholdLast').value,pointsMode=$('thresholdPoints').value,analysis=CORE.analyzeThreshold(thresholdRecords(),line,{lastN,pointsMode}),outcome=(name,count,pct)=>`<div class="thresholdOutcome ${name.toLowerCase()}"><strong>${name}</strong><b>${count}/${analysis.sample}</b><span>${thresholdNumber(pct,1)}%</span></div>`,metric=(label,value,digits=1)=>`<div class="thresholdMetric"><strong>${thresholdNumber(value,digits)}</strong><span>${label}</span></div>`;
  if(analysis.threshold===null){$('thresholdOutput').innerHTML='<div class="panel empty">Wpisz prawidłową wartość progu.</div>';return}
  const list=[...analysis.results].reverse().map(item=>{const r=item.record,click=item.record.eventKey?' clickable':'';return `<article class="thresholdRecord${click}" ${item.record.eventKey?`data-threshold-event="${esc(item.record.eventKey)}"`:''}><div><h4>${esc(r.season)} • ${esc(r.track||r.competition||r.league||'Wynik')}</h4><p>${esc([r.league,r.competition,r.home&&r.away?`${r.home} – ${r.away}`:'',r.homeAway==='HOME'?'dom':r.homeAway==='AWAY'?'wyjazd':''].filter(Boolean).join(' • '))}</p></div><div class="thresholdValue"><b>${esc(r.points||'—')} pkt</b><span class="thresholdBadge ${item.outcome.toLowerCase()}">${item.outcome} ${thresholdNumber(analysis.threshold,1)}</span></div></article>`}).join('');
  $('thresholdOutput').innerHTML=`<div class="panel"><div class="comparisonScope">Analiza progu: ${thresholdNumber(analysis.threshold,1)} pkt • ${esc(playerScope())}</div><div class="thresholdSummary">${outcome('OVER',analysis.over,analysis.overPct)}${outcome('UNDER',analysis.under,analysis.underPct)}${outcome('PUSH',analysis.push,analysis.pushPct)}</div><div class="thresholdSample">Próba: <b>${analysis.sample} startów</b> • ${analysis.sampleLabel}</div><div class="thresholdMetrics">${metric('średnia',analysis.mean)}${metric('mediana',analysis.median)}${metric('minimum',analysis.min)}${metric('maksimum',analysis.max)}${metric('średnia biegowa',analysis.heatAverage,3)}${metric('śr. liczba biegów',analysis.averageHeats,2)}${metric('odchylenie standardowe',analysis.standardDeviation,2)}${metric('rozpoznane biegi',analysis.heats,0)}</div><div class="chartHeading"><h3>Kolejne wyniki i linia progu</h3></div><div class="chartBox">${thresholdChart(analysis)}</div><p class="thresholdDisclaimer">To historyczny opis próby, nie prognoza ani rekomendacja zakładu. Przy opcji „Punkty + bonusy” niejednoznaczne zapisy są pomijane.</p></div><div class="thresholdListTitle">Rekordy użyte do analizy</div>${list||'<div class="panel empty">Brak wiarygodnych wyników liczbowych dla wybranego zakresu.</div>'}`;
  $('thresholdOutput').querySelectorAll('[data-threshold-event]').forEach(card=>card.onclick=()=>{const ref=eventKeyMap.get(card.dataset.thresholdEvent);if(ref)openEventDetail(ref[0],ref[1],'profile')});
  $('quickThresholds').querySelectorAll('button').forEach(button=>button.classList.toggle('active',Number(button.dataset.line)===analysis.threshold));
}

const _selectPlayerV44=selectPlayer;
selectPlayer=function(pid){playerView='results';const result=_selectPlayerV44(pid);$('playerNav').classList.remove('hidden');setPlayerView('results',{historyUpdate:false});$('playerScope').textContent=playerScope();return result};
const _goHomeV44=goHome;goHome=function(){hidePlayerV44();return _goHomeV44()};
const _openEventsV44=openEvents;openEvents=function(){hidePlayerV44();return _openEventsV44()};
const _openCompareV44=openCompare;openCompare=function(pid=null){hidePlayerV44();return _openCompareV44(pid)};
const _openEventDetailV44=openEventDetail;openEventDetail=function(y,ei,from='events'){hidePlayerV44();return _openEventDetailV44(y,ei,from)};

const _currentRouteV44=currentRoute;
currentRoute=function(){const route=_currentRouteV44();if(route.view!=='player')return route;return {...route,profileView:playerView,threshold:$('thresholdLine').value,season:$('season').value,league:$('league').value,competition:$('comp').value,track:$('track').value,homeAway:$('thresholdPlace').value,lastN:+$('thresholdLast').value,pointsMode:$('thresholdPoints').value}};
const _captureViewContextV44=captureViewContext;
captureViewContext=function(){const context=_captureViewContextV44();if(context.route.view==='player'){context.controls={...(context.controls||{}),...controlValues(['thresholdLine','thresholdPlace','thresholdLast','thresholdPoints'])};context.playerView=playerView}return context};
const _applyRouteV44=applyRoute;
applyRoute=async function(route,context=null){await _applyRouteV44(route,context);const next=CORE.normalizeRoute(route);if(next.view!=='player'||currentPid===null)return;setControlValues({season:next.season,league:next.league,comp:next.competition,track:next.track,thresholdLine:next.threshold??'8,5',thresholdPlace:next.homeAway,thresholdLast:String(next.lastN||0),thresholdPoints:next.pointsMode});if(context?.controls)setControlValues(context.controls);applyFilters();setPlayerView(context?.playerView||next.profileView,{historyUpdate:false})};

$('quickThresholds').innerHTML=[5.5,6.5,7.5,8.5,9.5,10.5,11.5].map(line=>`<button type="button" data-line="${line}">${String(line).replace('.',',')}</button>`).join('');
$('quickThresholds').querySelectorAll('button').forEach(button=>button.onclick=()=>{$('thresholdLine').value=String(button.dataset.line).replace('.',',');renderThreshold();persistHistoryContext()});
$('playerTabs').querySelectorAll('[data-player-view]').forEach(button=>button.onclick=()=>setPlayerView(button.dataset.playerView));
['season','league','comp','track'].forEach(id=>$(id).addEventListener('change',()=>{applyFilters();persistHistoryContext()}));
$('within').addEventListener('input',()=>{applyFilters();persistHistoryContext()});
['thresholdLine','thresholdPlace','thresholdLast','thresholdPoints'].forEach(id=>$(id).addEventListener(id==='thresholdLine'?'input':'change',()=>{renderThreshold();persistHistoryContext()}));
$('playerShare').onclick=()=>{if(currentPid!==null)void shareUrl(`Wyniki: ${DB.players[currentPid][0]}`,CORE.urlForRoute(location.href,currentRoute()))};

startup();
